+  bucket = aws_s3_bucket.drill.id
+  versioning_configuration { status = "Enabled" }
+}
+resource "aws_sqs_queue" "drill" {
+  name = "${local.p}-teardown-drill"
+}
+resource "aws_cloudwatch_log_group" "drill" {
+  name = "${local.p}-teardown-drill"
+  retention_in_days = 14
